import { Component } from '@angular/core';
import { PieService } from '../../services/pie.service';
import { NgFor, NgIf, AsyncPipe } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';

@Component({
  standalone: true,
  imports: [
    NgFor,
    NgIf,
    AsyncPipe,
    MatButtonModule,
  ],
  selector: 'app-detail-view',
  templateUrl: './detail-view.component.html',
  styleUrls: ['./detail-view.component.css']
})
export class DetailViewComponent {
  selectedPie$ = this.pieService.selectedPie$;
  constructor(private readonly pieService: PieService,){}
}
<div class="detail" *ngIf="selectedPie$ | async as selectedPie">
  <h3>{{ selectedPie.title }}</h3>
  <div class="image-wrapper">
    <img [src]="selectedPie.image" [alt]="selectedPie.title" />
    <div class="description">
      <p>{{ selectedPie.description }}</p>
      <h4>Ingredients: <span class="ingredient" *ngFor="let ingredient of selectedPie.ingredients">{{ ingredient }}</span></h4>
      <p class="price">Price: <span>{{ selectedPie.price }}</span></p>
    </div>
  </div>

  <button mat-raised-button>Add To Cart</button>
</div>
